import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


cpp_decl = r"""
#include <torch/extension.h>

torch::Tensor cute_sigmoid(torch::Tensor x);
"""


cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename scalar_t>
__global__ void cute_sigmoid_kernel(
    const scalar_t* x,
    scalar_t* y,
    int64_t total)
{
    auto gx = make_tensor(
        make_gmem_ptr(x),
        make_shape(total),
        make_stride(Int<1>{}));

    auto gy = make_tensor(
        make_gmem_ptr(y),
        make_shape(total),
        make_stride(Int<1>{}));

    int64_t index = static_cast<int64_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    int64_t stride = static_cast<int64_t>(blockDim.x) * gridDim.x;

    for (int64_t i = index; i < total; i += stride) {
        float value = static_cast<float>(gx(i));
        float result = 1.0f / (1.0f + expf(-value));
        gy(i) = static_cast<scalar_t>(result);
    }
}

torch::Tensor cute_sigmoid(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(
        x.scalar_type() == at::kFloat ||
        x.scalar_type() == at::kHalf ||
        x.scalar_type() == at::kBFloat16,
        "x must be float32, float16, or bfloat16");

    auto x_contiguous = x.contiguous();
    auto output = torch::empty_like(x_contiguous);
    int64_t total = x_contiguous.numel();

    if (total == 0) {
        return output;
    }

    constexpr int threads = 256;
    int blocks = static_cast<int>((total + threads - 1) / threads);
    blocks = min(blocks, 65535);

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    AT_DISPATCH_FLOATING_TYPES_AND2(
        at::kHalf,
        at::kBFloat16,
        x_contiguous.scalar_type(),
        "cute_sigmoid",
        [&] {
            cute_sigmoid_kernel<scalar_t><<<blocks, threads, 0, stream>>>(
                x_contiguous.data_ptr<scalar_t>(),
                output.data_ptr<scalar_t>(),
                total);
        });

    TORCH_CHECK(
        cudaGetLastError() == cudaSuccess,
        "CUTE sigmoid kernel launch failed");

    return output;
}
"""


cute_ext = load_inline(
    name="cute_sigmoid_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_sigmoid"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=[
        "-O3",
        "-I/root/cutegen_test/cutegen/cutlass/include",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self._ext = cute_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_sigmoid(x)

